settings.custom_css:
  div#call-cta-ip p.elementor-image-box-description a{
      color: #fff!important;
  }
  div#call-cta-ip p.elementor-image-box-description a:hover{
      color: #D4B351!important;
  }
@media (max-width: 767px){
  div#call-cta-ip.elementor-widget-image-box .elementor-image-box-wrapper {
    display: flex !important;
    align-items: center;
}  
div#call-cta-ip .elementor-image-box-content {
    text-align: left;
    margin-left: 15px;
}
}

.elementor-nav-menu__align-justify .elementor-nav-menu--layout-horizontal .elementor-nav-menu>li:before{
    content: "";
    position: absolute;
    background: #fff;
    height: 8px;
    width: 8px;
    border-radius: 50px;
    top: 50%;
    left: 0;
    transform: translate(-50%, -50%);
}
.elementor-nav-menu__align-justify .elementor-nav-menu--layout-horizontal .elementor-nav-menu>li:nth-child(1):before{
    display: none;
}

span.elementor-toggle-icon-closed, span.elementor-toggle-icon-opened {
 
 margin-left: -10px;
}
span.elementor-toggle-icon-closed i{
 padding: 15px 17px;
 background: #0c4f4d;
 border-radius: 50px;
}
span.elementor-toggle-icon-opened i {
 padding: 13px 24px 13px 22px!important;
 background: #fbf6e1!important;
 border-radius: 50px!important;
}
.elementor-18 .elementor-element.elementor-element-8d56251 .elementor-tab-title.elementor-active .elementor-toggle-icon i:before {
 margin-left: -7px;
}
div.elementor-tab-title {
 display: flex;
 align-items: center;
 flex-direction: row-reverse;
 justify-content: space-between;
}
.elementor-toggle .elementor-tab-title{
 border: 2px solid #cfd8d7; 
}
.elementor-tab-title {
 border-radius: 50px;
}
.elementor-tab-title.elementor-active{
 border-radius: 50px 50px 0px 0px;
 border-top: 2px solid #d4b352;
 border-left: 2px solid #d4b352;
 border-right: 2px solid #d4b352;
}
.elementor-toggle .elementor-tab-content{
 border-radius: 0px 0px 50px 50px;
 border-bottom: 2px solid #d4b352;
 border-left: 2px solid #d4b352;
 border-right: 2px solid #d4b352;
}
.elementor-tab-title.elementor-active, .elementor-toggle .elementor-tab-content{
 background: url(/wp-content/uploads/2024/04/bg-toggle.png);
}
@media (max-width: 767px){
 span.elementor-toggle-icon-closed i{
 transform: scale(0.6);
}
span.elementor-toggle-icon-opened i {
 transform: scale(0.7);
}
}
